mappedOutcome:
onPress: () => {
          if (isFlipped) {
            flip();
          } else {
            onTap?.();
          }
        }; onLongPress: flip

onPressIn: (ev) => {
        if (process.env.EXPO_OS === 'ios') {
          // Add a soft haptic feedback when pressing down on the tabs.
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        }
        props.onPressIn?.(ev);
      }

onPress: onPress; onPressIn: () => {
        press();
        scale.value = withSpring(0.98, { damping: 15, stiffness: 150 });
      }; onPressOut: () => {
        scale.value = withSpring(1, { damping: 15, stiffness: 150 });
      }

onSave: () => {
                if (featured) void save(featured);
              }; onPreview: () => {
                if (featured) openGame(featured);
              }

onLayout: (e) => {
          if (measuredHeight.current === 0) {
            const h = e.nativeEvent.layout.height;
            measuredHeight.current = h;
            collapseHeight.value = h;
          }
        }

onStartShouldSetResponder: () => true; onMoveShouldSetResponder: () => true; onTouchStart: () => {
          // Disable scroll immediately when touching slider area
          onDragStart?.();
        }; onTouchEnd: () => {
          // Re-enable scroll after touch ends (with delay)
          setTimeout(() => {
            onDragEnd?.();
          }, 150);
        }

onValueChange: setLocalValue; onSlidingStart: () => {
            setIsDragging(true);
          }; onSlidingComplete: (val) => {
            setIsDragging(false);
            onChange(val);
          }
